/**
 * @fileoverview Tests for no-empty rule.
 * @author Nicholas C. Zakas
 */

"use strict";

//------------------------------------------------------------------------------
// Requirements
//------------------------------------------------------------------------------

const rule = require("../../../lib/rules/no-empty"),
	RuleTester = require("../../../lib/rule-tester/rule-tester");

//------------------------------------------------------------------------------
// Tests
//------------------------------------------------------------------------------

const ruleTester = new RuleTester();

ruleTester.run("no-empty", rule, {
	valid: [
		"if (foo) { bar() }",
		"while (foo) { bar() }",
		"for (;foo;) { bar() }",
		"try { foo() } catch (ex) { foo() }",
		"switch(foo) {case 'foo': break;}",
		"(function() { }())",
		{ code: "var foo = () => {};", languageOptions: { ecmaVersion: 6 } },
		"function foo() { }",
		"if (foo) {/* empty */}",
		"while (foo) {/* empty */}",
		"switch (foo) {/* empty */}",
		"for (;foo;) {/* empty */}",
		"try { foo() } catch (ex) {/* empty */}",
		"try { foo() } catch (ex) {// empty\n}",
		"try { foo() } finally {// empty\n}",
		"try { foo() } finally {// test\n}",
		"try { foo() } finally {\n \n // hi i am off no use\n}",
		"try { foo() } catch (ex) {/* test111 */}",
		"if (foo) { bar() } else { // nothing in me \n}",
		"if (foo) { bar() } else { /**/ \n}",
		"if (foo) { bar() } else { // \n}",
		{
			code: "try { foo(); } catch (ex) {}",
			options: [{ allowEmptyCatch: true }],
		},
		{
			code: "try { foo(); } catch (ex) {} finally { bar(); }",
			options: [{ allowEmptyCatch: true }],
		},
	],
	invalid: [
		{
			code: "try {} catch (ex) {throw ex}",
			errors: [
				{
					messageId: "unexpected",
					data: { type: "block" },
					type: "BlockStatement",
					suggestions: [
						{
							messageId: "suggestComment",
							data: { type: "block" },
							output: "try { /* empty */ } catch (ex) {throw ex}",
						},
					],
				},
			],
		},
		{
			code: "try { foo() } catch (ex) {}",
			errors: [
				{
					messageId: "unexpected",
					data: { type: "block" },
					type: "BlockStatement",
					suggestions: [
						{
							messageId: "suggestComment",
							data: { type: "block" },
							output: "try { foo() } catch (ex) { /* empty */ }",
						},
					],
				},
			],
		},
		{
			code: "try { foo() } catch (ex) {throw ex} finally {}",
			errors: [
				{
					messageId: "unexpected",
					data: { type: "block" },
					type: "BlockStatement",
					suggestions: [
						{
							messageId: "suggestComment",
							data: { type: "block" },
							output: "try { foo() } catch (ex) {throw ex} finally { /* empty */ }",
						},
					],
				},
			],
		},
		{
			code: "if (foo) {}",
			errors: [
				{
					messageId: "unexpected",
					data: { type: "block" },
					type: "BlockStatement",
					suggestions: [
						{
							messageId: "suggestComment",
							data: { type: "block" },
							output: "if (foo) { /* empty */ }",
						},
					],
				},
			],
		},
		{
			code: "while (foo) {}",
			errors: [
				{
					messageId: "unexpected",
					data: { type: "block" },
					type: "BlockStatement",
					suggestions: [
						{
							messageId: "suggestComment",
							data: { type: "block" },
							output: "while (foo) { /* empty */ }",
						},
					],
				},
			],
		},
		{
			code: "for (;foo;) {}",
			errors: [
				{
					messageId: "unexpected",
					data: { type: "block" },
					type: "BlockStatement",
					suggestions: [
						{
							messageId: "suggestComment",
							data: { type: "block" },
							output: "for (;foo;) { /* empty */ }",
						},
					],
				},
			],
		},
		{
			code: "switch(foo) {}",
			errors: [
				{
					messageId: "unexpected",
					data: { type: "switch" },
					type: "SwitchStatement",
					line: 1,
					column: 13,
					endLine: 1,
					endColumn: 15,
					suggestions: [
						{
							messageId: "suggestComment",
							data: { type: "switch" },
							output: "switch(foo) { /* empty */ }",
						},
					],
				},
			],
		},
		{
			code: "switch /* empty */ (/* empty */ foo /* empty */) /* empty */ {} /* empty */",
			errors: [
				{
					messageId: "unexpected",
					data: { type: "switch" },
					type: "SwitchStatement",
					line: 1,
					column: 62,
					endLine: 1,
					endColumn: 64,
					suggestions: [
						{
							messageId: "suggestComment",
							data: { type: "switch" },
							output: "switch /* empty */ (/* empty */ foo /* empty */) /* empty */ { /* empty */ } /* empty */",
						},
					],
				},
			],
		},
		{
			code: "try {} catch (ex) {}",
			options: [{ allowEmptyCatch: true }],
			errors: [
				{
					messageId: "unexpected",
					data: { type: "block" },
					type: "BlockStatement",
					suggestions: [
						{
							messageId: "suggestComment",
							data: { type: "block" },
							output: "try { /* empty */ } catch (ex) {}",
						},
					],
				},
			],
		},
		{
			code: "try { foo(); } catch (ex) {} finally {}",
			options: [{ allowEmptyCatch: true }],
			errors: [
				{
					messageId: "unexpected",
					data: { type: "block" },
					type: "BlockStatement",
					suggestions: [
						{
							messageId: "suggestComment",
							data: { type: "block" },
							output: "try { foo(); } catch (ex) {} finally { /* empty */ }",
						},
					],
				},
			],
		},
		{
			code: "try {} catch (ex) {} finally {}",
			options: [{ allowEmptyCatch: true }],
			errors: [
				{
					messageId: "unexpected",
					data: { type: "block" },
					type: "BlockStatement",
					suggestions: [
						{
							messageId: "suggestComment",
							data: { type: "block" },
							output: "try { /* empty */ } catch (ex) {} finally {}",
						},
					],
				},
				{
					messageId: "unexpected",
					data: { type: "block" },
					type: "BlockStatement",
					suggestions: [
						{
							messageId: "suggestComment",
							data: { type: "block" },
							output: "try {} catch (ex) {} finally { /* empty */ }",
						},
					],
				},
			],
		},
		{
			code: "try { foo(); } catch (ex) {} finally {}",
			errors: [
				{
					messageId: "unexpected",
					data: { type: "block" },
					type: "BlockStatement",
					suggestions: [
						{
							messageId: "suggestComment",
							data: { type: "block" },
							output: "try { foo(); } catch (ex) { /* empty */ } finally {}",
						},
					],
				},
				{
					messageId: "unexpected",
					data: { type: "block" },
					type: "BlockStatement",
					suggestions: [
						{
							messageId: "suggestComment",
							data: { type: "block" },
							output: "try { foo(); } catch (ex) {} finally { /* empty */ }",
						},
					],
				},
			],
		},
	],
});
